from enum import Enum

from pydantic import BaseModel, Field, validator

logger = logging.getLogger(__name__)


class LogLevel(str, Enum):
    DEBUG = "DEBUG"
    INFO = "INFO"
    WARNING = "WARNING"
    ERROR = "ERROR"
    CRITICAL = "CRITICAL"


class DatabaseType(str, Enum):
    SQLITE = "sqlite"
    POSTGRESQL = "postgresql"
    MYSQL = "mysql"
    MONGODB = "mongodb"


class RetentionPolicy(str, Enum):
    DAYS_7 = "7_days"
    DAYS_30 = "30_days"
    DAYS_90 = "90_days"
    PERMANENT = "permanent"


class DatabaseSettings(BaseModel):
    connection_string: str = Field(default="", description="Database connection string")
    database_type: DatabaseType = Field(default=DatabaseType.SQLITE)
    template: str = Field(default="basic", description="Database template to use")
    pool_size: int = Field(default=10, ge=1, le=100, description="Connection pool size")
    echo_sql: bool = Field(default=False, description="Echo SQL statements to logs")
    migration_auto: bool = Field(default=True, description="Enable automatic migrations")
    backup_enabled: bool = Field(default=False, description="Enable automatic backups")
    backup_interval_hours: int = Field(default=24, ge=1, le=720)

    @validator("connection_string")
    def validate_connection_string(cls, v: str) -> str:
        if not v or not v.strip():
            return v
        valid_prefixes = [
            "sqlite://",
            "postgresql://",
            "mysql://",
            "mongodb://",
            "mongodb+srv://",
        ]
        if not any(v.startswith(prefix) for prefix in valid_prefixes):
            raise ValueError("Invalid database connection string prefix")
        return v


